import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.CdvW4CUT.js";const p=JSON.parse('{"title":"Kernel 日报 2026-11-24","description":"","frontmatter":{},"headers":[],"relativePath":"notes/kernel-digest/2026/11/24.md","filePath":"notes/kernel-digest/2026/11/24.md"}'),l={name:"notes/kernel-digest/2026/11/24.md"};function n(s,e,i,c,d,m){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="kernel-日报-2026-11-24" tabindex="-1">Kernel 日报 2026-11-24 <a class="header-anchor" href="#kernel-日报-2026-11-24" aria-label="Permalink to &quot;Kernel 日报 2026-11-24&quot;">​</a></h1><blockquote><p>生成时间：2026-11-24T01:27:44Z｜共 34 条</p></blockquote><blockquote><p>深读：使用条目前 12 位 id，运行 <code>python -m kernel_digest deep --date 2026-11-24 --id &lt;id&gt;</code>。</p></blockquote><h2 id="今日-top-5" tabindex="-1">今日 Top 5 <a class="header-anchor" href="#今日-top-5" aria-label="Permalink to &quot;今日 Top 5&quot;">​</a></h2><h3 id="f1a6305a1f0f-·-syzbot-kernfs-kasan-slab-use-after-free-read-in-kernfs-find-ns" tabindex="-1"><code>f1a6305a1f0f</code> · <a href="https://lore.kernel.org/all/6b04e3d0.44b41460.34b83f.0035.GAE@google.com/" target="_blank" rel="noreferrer">[syzbot] [kernfs?] KASAN: slab-use-after-free Read in kernfs_find_ns</a> <a class="header-anchor" href="#f1a6305a1f0f-·-syzbot-kernfs-kasan-slab-use-after-free-read-in-kernfs-find-ns" aria-label="Permalink to &quot;`f1a6305a1f0f` · [[syzbot] [kernfs?] KASAN: slab-use-after-free Read in kernfs_find_ns](https://lore.kernel.org/all/6b04e3d0.44b41460.34b83f.0035.GAE@google.com/)&quot;">​</a></h3><p><em>syzbot (<a href="mailto:syzbot+8c2fa00c27ecafd148f5@syzkaller.appspotmail.com" target="_blank" rel="noreferrer">syzbot+8c2fa00c27ecafd148f5@syzkaller.appspotmail.com</a>)｜lkml｜内存管理</em></p><p>syzbot 在 upstream 最新代码上报告了 kernfs_find_ns 中的 slab-use-after-free 读问题，由 KASAN 检测到，目前尚无 reproducer。该问题位于 kernfs 子系统，可能涉及 sysfs/cgroup 文件系统的命名空间查找路径。</p><blockquote><p><strong>学习价值</strong>：典型的 syzbot+KASAN 报告案例，适合学习如何阅读 UAF 报告、分析 kernfs 引用计数与生命周期管理。</p></blockquote><h3 id="_0f48e6f5dea1-·-patch-net-v7-6-9-ipv6-don-t-send-redirects-for-decrypted-skbs" tabindex="-1"><code>0f48e6f5dea1</code> · <a href="https://lore.kernel.org/all/20261124010601.3995693-7-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net v7 6/9] ipv6: don&#39;t send redirects for decrypted skbs</a> <a class="header-anchor" href="#_0f48e6f5dea1-·-patch-net-v7-6-9-ipv6-don-t-send-redirects-for-decrypted-skbs" aria-label="Permalink to &quot;`0f48e6f5dea1` · [[PATCH net v7 6/9] ipv6: don&#39;t send redirects for decrypted skbs](https://lore.kernel.org/all/20261124010601.3995693-7-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜lkml｜网络</em></p><p>修复 IPv6 转发路径上的明文泄露：当 ip6_forward() 将包从进入的接口转发回去时，会通过 ndisc_send_redirect() 发送 NDISC Redirect，其 Redirected Header 选项会引用原包内容。若设备已解密该包（skb-&gt;decrypted 置位），redirect 会把明文片段发回网络，因此对已解密的 skb 不再发送 redirect。IPv4 的 redirect 走 __icmp_send() 已被前序补丁覆盖。</p><blockquote><p><strong>学习价值</strong>：展示了加密流量与 ICMPv6 redirect 的交互泄露问题，对理解 skb-&gt;decrypted 标志和 ndisc 实现很有帮助。</p></blockquote><h3 id="_032ef42c1a39-·-rfc-patch-mm-memcontrol-let-a-cgroup-opt-out-of-hugetlb-accounting" tabindex="-1"><code>032ef42c1a39</code> · <a href="https://lore.kernel.org/all/20261124003145.80705-1-harpatil@redhat.com/" target="_blank" rel="noreferrer">[RFC PATCH] mm: memcontrol: let a cgroup opt out of HugeTLB accounting</a> <a class="header-anchor" href="#_032ef42c1a39-·-rfc-patch-mm-memcontrol-let-a-cgroup-opt-out-of-hugetlb-accounting" aria-label="Permalink to &quot;`032ef42c1a39` · [[RFC PATCH] mm: memcontrol: let a cgroup opt out of HugeTLB accounting](https://lore.kernel.org/all/20261124003145.80705-1-harpatil@redhat.com/)&quot;">​</a></h3><p><em>Harshal Patil (<a href="mailto:harpatil@redhat.com" target="_blank" rel="noreferrer">harpatil@redhat.com</a>)｜linux-mm｜内存管理</em></p><p>该 RFC 提议允许单个 cgroup 选择退出 HugeTLB 记账。当前 memory_hugetlb_accounting 挂载选项是全局的，对所有 cgroup 生效或都不生效，这对 Kubernetes 等将 huge pages 作为独立资源（hugetlb.&lt;size&gt;.max）管理的场景造成问题，pod 的 HugeTLB 预算会被 memory.max 重复限制。</p><blockquote><p><strong>学习价值</strong>：深入剖析了 memcg 与 HugeTLB 记账的交互及容器化场景的痛点，是学习 cgroup v2 内存控制器设计的优秀案例。</p></blockquote><h3 id="cd7120856f0e-·-patch-v5-12-18-mm-shmem-luo-allow-preserving-tmpfs-files" tabindex="-1"><code>cd7120856f0e</code> · <a href="https://lore.kernel.org/all/20261123233924.3970932-13-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v5 12/18] mm/shmem_luo: Allow preserving tmpfs files</a> <a class="header-anchor" href="#cd7120856f0e-·-patch-v5-12-18-mm-shmem-luo-allow-preserving-tmpfs-files" aria-label="Permalink to &quot;`cd7120856f0e` · [[PATCH v5 12/18] mm/shmem_luo: Allow preserving tmpfs files](https://lore.kernel.org/all/20261123233924.3970932-13-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm｜内存管理</em></p><p>通过移除 shmem_luo_can_preserve() 中的链接数检查，允许保留 tmpfs 挂载上的文件。该检查原本用于将保留限制在从无链接的 memfd 上，现在 tmpfs 文件可检索到用户创建的文件中，不再需要。用户空间可继续通过路径使用链接文件直到 Live Update；文件路径不被保留，用户需创建检索目标文件并可自行链接到期望路径。保留链接文件会影响所有通过路径打开它的用户，因为保留期间大小被冻结。</p><blockquote><p><strong>学习价值</strong>：展示了功能演进中放宽约束的设计权衡，以及保留语义对共享文件的多方影响。</p></blockquote><h3 id="_7008bcfb6f4d-·-rfc-patch-0-3-rust-dma-require-device-configuration-before-dma" tabindex="-1"><code>7008bcfb6f4d</code> · <a href="https://lore.kernel.org/all/20261123203926.1787169-1-kernel@matt3o12.de/" target="_blank" rel="noreferrer">[RFC PATCH 0/3] rust: dma: require device configuration before DMA</a> <a class="header-anchor" href="#_7008bcfb6f4d-·-rfc-patch-0-3-rust-dma-require-device-configuration-before-dma" aria-label="Permalink to &quot;`7008bcfb6f4d` · [[RFC PATCH 0/3] rust: dma: require device configuration before DMA](https://lore.kernel.org/all/20261123203926.1787169-1-kernel@matt3o12.de/)&quot;">​</a></h3><p><em>Matteo Kloiber (<a href="mailto:kernel@matt3o12.de" target="_blank" rel="noreferrer">kernel@matt3o12.de</a>)｜rust-for-linux｜Rust in Linux</em></p><p>该 RFC 源自关于 max_seg_size 的讨论，实现了通过 InitTokens 传递给 probe() 的 DMA setup token 机制。驱动必须先调用 configure() 消耗 token 并设置 dma::Params（如 streaming_mask、coherent_mask、max_seg_size），才能获得可复制的 dma::Handle 并进行 Coherent 分配或映射。这从类型系统层面强制驱动在 DMA 操作前正确完成设备配置。</p><blockquote><p><strong>学习价值</strong>：展示了如何用 Rust 类型状态（typestate）模式将内核 DMA 配置顺序编码进 API，是学习 Rust 安全抽象设计的优秀案例。</p></blockquote><h2 id="分类目录" tabindex="-1">分类目录 <a class="header-anchor" href="#分类目录" aria-label="Permalink to &quot;分类目录&quot;">​</a></h2><ul><li><strong>内存管理</strong>（16 条）</li><li><strong>网络</strong>（5 条）</li><li><strong>Rust in Linux</strong>（8 条）</li><li><strong>跟踪与性能</strong>（2 条）</li><li><strong>版本发布动态</strong>（1 条）</li><li><strong>其他动态</strong>（2 条）</li></ul><h2 id="内存管理" tabindex="-1">内存管理 <a class="header-anchor" href="#内存管理" aria-label="Permalink to &quot;内存管理&quot;">​</a></h2><h3 id="f1a6305a1f0f-·-syzbot-kernfs-kasan-slab-use-after-free-read-in-kernfs-find-ns-1" tabindex="-1"><code>f1a6305a1f0f</code> · <a href="https://lore.kernel.org/all/6b04e3d0.44b41460.34b83f.0035.GAE@google.com/" target="_blank" rel="noreferrer">[syzbot] [kernfs?] KASAN: slab-use-after-free Read in kernfs_find_ns</a> <a class="header-anchor" href="#f1a6305a1f0f-·-syzbot-kernfs-kasan-slab-use-after-free-read-in-kernfs-find-ns-1" aria-label="Permalink to &quot;`f1a6305a1f0f` · [[syzbot] [kernfs?] KASAN: slab-use-after-free Read in kernfs_find_ns](https://lore.kernel.org/all/6b04e3d0.44b41460.34b83f.0035.GAE@google.com/)&quot;">​</a></h3><p><em>syzbot (<a href="mailto:syzbot+8c2fa00c27ecafd148f5@syzkaller.appspotmail.com" target="_blank" rel="noreferrer">syzbot+8c2fa00c27ecafd148f5@syzkaller.appspotmail.com</a>)｜lkml</em></p><p>syzbot 在 upstream 最新代码上报告了 kernfs_find_ns 中的 slab-use-after-free 读问题，由 KASAN 检测到，目前尚无 reproducer。该问题位于 kernfs 子系统，可能涉及 sysfs/cgroup 文件系统的命名空间查找路径。</p><blockquote><p><strong>学习价值</strong>：典型的 syzbot+KASAN 报告案例，适合学习如何阅读 UAF 报告、分析 kernfs 引用计数与生命周期管理。</p></blockquote><h3 id="_032ef42c1a39-·-rfc-patch-mm-memcontrol-let-a-cgroup-opt-out-of-hugetlb-accounting-1" tabindex="-1"><code>032ef42c1a39</code> · <a href="https://lore.kernel.org/all/20261124003145.80705-1-harpatil@redhat.com/" target="_blank" rel="noreferrer">[RFC PATCH] mm: memcontrol: let a cgroup opt out of HugeTLB accounting</a> <a class="header-anchor" href="#_032ef42c1a39-·-rfc-patch-mm-memcontrol-let-a-cgroup-opt-out-of-hugetlb-accounting-1" aria-label="Permalink to &quot;`032ef42c1a39` · [[RFC PATCH] mm: memcontrol: let a cgroup opt out of HugeTLB accounting](https://lore.kernel.org/all/20261124003145.80705-1-harpatil@redhat.com/)&quot;">​</a></h3><p><em>Harshal Patil (<a href="mailto:harpatil@redhat.com" target="_blank" rel="noreferrer">harpatil@redhat.com</a>)｜linux-mm</em></p><p>该 RFC 提议允许单个 cgroup 选择退出 HugeTLB 记账。当前 memory_hugetlb_accounting 挂载选项是全局的，对所有 cgroup 生效或都不生效，这对 Kubernetes 等将 huge pages 作为独立资源（hugetlb.&lt;size&gt;.max）管理的场景造成问题，pod 的 HugeTLB 预算会被 memory.max 重复限制。</p><blockquote><p><strong>学习价值</strong>：深入剖析了 memcg 与 HugeTLB 记账的交互及容器化场景的痛点，是学习 cgroup v2 内存控制器设计的优秀案例。</p></blockquote><h3 id="e2b64fcdf514-·-patch-memcg-free-the-private-id-of-a-memcg-that-never-comes-online" tabindex="-1"><code>e2b64fcdf514</code> · <a href="https://lore.kernel.org/all/20261124000439.967403-1-shakeel.butt@linux.dev/" target="_blank" rel="noreferrer">[PATCH] memcg: free the private ID of a memcg that never comes online</a> <a class="header-anchor" href="#e2b64fcdf514-·-patch-memcg-free-the-private-id-of-a-memcg-that-never-comes-online" aria-label="Permalink to &quot;`e2b64fcdf514` · [[PATCH] memcg: free the private ID of a memcg that never comes online](https://lore.kernel.org/all/20261124000439.967403-1-shakeel.butt@linux.dev/)&quot;">​</a></h3><p><em>Shakeel Butt (shakeel.butt@linux.dev)｜linux-mm</em></p><p>修复 memcg 的私有 ID 泄漏问题：mem_cgroup_alloc() 在分配 css 时预留私有 ID，但如果 css_create() 在 css_alloc() 之后、online_css() 之前失败（如 percpu_ref_init()、cgroup_idr_alloc() 或 css_rstat_init() 失败），memcg 会通过 mem_cgroup_css_free() 释放但从未上线，其 ID 不会被擦除，导致 mem_cgroup_private_ids 中永久残留保留条目。补丁确保该路径下也正确释放 ID。</p><blockquote><p><strong>学习价值</strong>：展示了 cgroup 子系统分配/上线/释放生命周期中引用与资源清理的细节，是学习错误路径资源管理的绝佳案例。</p></blockquote><h3 id="d238a7f83851-·-patch-slab-fix-the-kernel-doc-of-kmalloc-flex-on-counter-overflow" tabindex="-1"><code>d238a7f83851</code> · <a href="https://lore.kernel.org/all/20261124-slab-doc-v1-1-9f14dfce47c8@mbzuai.ac.ae/" target="_blank" rel="noreferrer">[PATCH] slab: fix the kernel-doc of kmalloc_flex() on counter overflow</a> <a class="header-anchor" href="#d238a7f83851-·-patch-slab-fix-the-kernel-doc-of-kmalloc-flex-on-counter-overflow" aria-label="Permalink to &quot;`d238a7f83851` · [[PATCH] slab: fix the kernel-doc of kmalloc_flex() on counter overflow](https://lore.kernel.org/all/20261124-slab-doc-v1-1-9f14dfce47c8@mbzuai.ac.ae/)&quot;">​</a></h3><p><em>Arina Kharlamova via B4 Relay (<a href="mailto:devnull+arina.kharlamova.mbzuai.ac.ae@kernel.org" target="_blank" rel="noreferrer">devnull+arina.kharlamova.mbzuai.ac.ae@kernel.org</a>)｜linux-mm</em></p><p>修正 kmalloc_flex() 的 kernel-doc 文档：commit fa5c82f4d2bb 移除了 __alloc_flex() 中的 overflows_flex_counter_type() 检查，但文档仍声称当 COUNT 无法被 __counted_by() 计数器表示时分配会失败。实际行为是分配 COUNT 个元素并将截断后的 COUNT 存入计数器，例如 u8 计数器下 kmalloc_flex(*p, array, 256) 会返回 256 元素对象。补丁同步更新文档和 deprecated.rst。</p><blockquote><p><strong>学习价值</strong>：提醒学习者内核文档与代码行为可能脱节，flex array 与 __counted_by() 的语义值得深入理解。</p></blockquote><h3 id="_2a33ba2e8993-·-patch-v5-18-18-selftests-liveupdate-test-block-accounting-of-retrieved-tmpfs-files" tabindex="-1"><code>2a33ba2e8993</code> · <a href="https://lore.kernel.org/all/20261123233924.3970932-19-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v5 18/18] selftests/liveupdate: Test block accounting of retrieved tmpfs files</a> <a class="header-anchor" href="#_2a33ba2e8993-·-patch-v5-18-18-selftests-liveupdate-test-block-accounting-of-retrieved-tmpfs-files" aria-label="Permalink to &quot;`2a33ba2e8993` · [[PATCH v5 18/18] selftests/liveupdate: Test block accounting of retrieved tmpfs files](https://lore.kernel.org/all/20261123233924.3970932-19-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>为 luo_tmpfs 自测程序添加 tmpfs 文件检索后 block 计费相关的测试用例：验证文件恰好占满挂载点空间、超出文件末尾的 large folio 被全额计费；挂载空间耗尽或触及 memcg 限制时检索永久失败、目标保持为空且不产生计费，会话仍可正常结束。large folio 测试需要 CONFIG_TRANSPARENT_HUGEPAGE，memcg 测试需要 CONFIG_CGROUPS 和 CONFIG_MEMCG，否则跳过。</p><blockquote><p><strong>学习价值</strong>：展示了如何用 statfs() 和 st_blocks 精确验证 tmpfs 的 block 计费与 memcg 交互，是学习内核测试设计的良好范例。</p></blockquote><h3 id="d8cc05b9775d-·-patch-v5-17-18-selftests-liveupdate-test-retrieving-tmpfs-files-preserved-read-only" tabindex="-1"><code>d8cc05b9775d</code> · <a href="https://lore.kernel.org/all/20261123233924.3970932-18-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v5 17/18] selftests/liveupdate: Test retrieving tmpfs files preserved read-only</a> <a class="header-anchor" href="#d8cc05b9775d-·-patch-v5-17-18-selftests-liveupdate-test-retrieving-tmpfs-files-preserved-read-only" aria-label="Permalink to &quot;`d8cc05b9775d` · [[PATCH v5 17/18] selftests/liveupdate: Test retrieving tmpfs files preserved read-only](https://lore.kernel.org/all/20261123233924.3970932-18-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>为 luo_tmpfs 添加只读方式保留 tmpfs 文件的测试用例：涵盖通过只读 fd、只读挂载、只读 superblock 保留的文件以及 immutable 文件。除第一种外均同时保留 sparse 文件并验证其空洞在保留时被填充。测试验证文件内容正确检索、保留期间文件大小被冻结（即使通过路径打开）、文件内的写入也被保留。</p><blockquote><p><strong>学习价值</strong>：帮助学习者理解 LUO（Live Update）机制中文件保留语义与只读/immutable 属性的交互。</p></blockquote><h3 id="_363a2c216a42-·-patch-v5-16-18-selftests-liveupdate-test-the-targets-of-retrieved-tmpfs-files" tabindex="-1"><code>363a2c216a42</code> · <a href="https://lore.kernel.org/all/20261123233924.3970932-17-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v5 16/18] selftests/liveupdate: Test the targets of retrieved tmpfs files</a> <a class="header-anchor" href="#_363a2c216a42-·-patch-v5-16-18-selftests-liveupdate-test-the-targets-of-retrieved-tmpfs-files" aria-label="Permalink to &quot;`363a2c216a42` · [[PATCH v5 16/18] selftests/liveupdate: Test the targets of retrieved tmpfs files](https://lore.kernel.org/all/20261123233924.3970932-17-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>为 luo_tmpfs 添加检索目标文件的测试用例：目标必须以写模式打开（可以是 write-only）并保留其文件状态标志；必须是 tmpfs 挂载上的空普通文件，含数据、非零大小或末尾后 block 的文件以及 memfd、pipe、目录、immutable 文件均被拒绝，且失败后可换文件重试。还验证非特权进程可检索到自己创建的文件（保留 owner 和 mode）、运行中的二进制可通过只读 fd 保留。</p><blockquote><p><strong>学习价值</strong>：详细展示了 LUO 检索接口的约束条件设计，对理解内核 API 的权限与状态校验逻辑很有帮助。</p></blockquote><h3 id="ed17dafb4cff-·-patch-v5-15-18-selftests-liveupdate-test-memfds-and-luo-interactions-in-luo-tmpfs" tabindex="-1"><code>ed17dafb4cff</code> · <a href="https://lore.kernel.org/all/20261123233924.3970932-16-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v5 15/18] selftests/liveupdate: Test memfds and LUO interactions in luo_tmpfs</a> <a class="header-anchor" href="#ed17dafb4cff-·-patch-v5-15-18-selftests-liveupdate-test-memfds-and-luo-interactions-in-luo-tmpfs" aria-label="Permalink to &quot;`ed17dafb4cff` · [[PATCH v5 15/18] selftests/liveupdate: Test memfds and LUO interactions in luo_tmpfs](https://lore.kernel.org/all/20261123233924.3970932-16-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>为 luo_tmpfs 添加 memfd 与 LUO 交互的测试：memfd 检索后仍是 memfd 并保留 seals 和文件位置，且只能不带 retrieve 参数检索；tmpfs 文件则必须带参数检索。验证无效 retrieve 参数失败后可修复重试；带参数重复检索同一 token 返回 -EBUSY，不带参数则返回同一打开文件；不能从 outgoing 会话检索文件；已被 LUO 管理的文件不能作为检索目标。</p><blockquote><p><strong>学习价值</strong>：通过测试用例清晰呈现 LUO 会话状态机的边界条件，适合学习内核接口的幂等性与错误处理设计。</p></blockquote><h3 id="d732a10e3985-·-patch-v5-14-18-selftests-liveupdate-add-a-test-for-retrieving-tmpfs-files" tabindex="-1"><code>d732a10e3985</code> · <a href="https://lore.kernel.org/all/20261123233924.3970932-15-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v5 14/18] selftests/liveupdate: Add a test for retrieving tmpfs files</a> <a class="header-anchor" href="#d732a10e3985-·-patch-v5-14-18-selftests-liveupdate-add-a-test-for-retrieving-tmpfs-files" aria-label="Permalink to &quot;`d732a10e3985` · [[PATCH v5 14/18] selftests/liveupdate: Add a test for retrieving tmpfs files](https://lore.kernel.org/all/20261123233924.3970932-15-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>新增 luo_tmpfs kexec 测试框架，用于验证 tmpfs 文件保留及通过 struct liveupdate_shmem_retrieve_arg 检索到 tmpfs 挂载上的文件。Stage 1 保留各测试用例的源文件，Stage 2 在各自独立目录和 tmpfs 挂载中运行用例，以便用 statfs() 和 st_blocks 精确检查 block 使用。首批用例验证检索文件的内容、大小和空洞，覆盖链接文件和 O_TMPFILE 创建的文件。</p><blockquote><p><strong>学习价值</strong>：展示了两阶段 kexec 测试框架的搭建方式，是学习内核自测程序结构设计的实用参考。</p></blockquote><h3 id="_5f27b43daa9e-·-patch-v5-13-18-selftests-liveupdate-test-which-tmpfs-files-can-be-preserved" tabindex="-1"><code>5f27b43daa9e</code> · <a href="https://lore.kernel.org/all/20261123233924.3970932-14-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v5 13/18] selftests/liveupdate: Test which tmpfs files can be preserved</a> <a class="header-anchor" href="#_5f27b43daa9e-·-patch-v5-13-18-selftests-liveupdate-test-which-tmpfs-files-can-be-preserved" aria-label="Permalink to &quot;`5f27b43daa9e` · [[PATCH v5 13/18] selftests/liveupdate: Test which tmpfs files can be preserved](https://lore.kernel.org/all/20261123233924.3970932-14-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>为 liveupdate.c 添加 tmpfs 文件保留条件检查的测试：文件可通过只读 fd 保留但不能通过 write-only fd；保留需要对文件的写权限，但 immutable 文件所有者和只读 superblock 上文件的所有者除外；append-only 文件不能保留；只读挂载上的文件可以保留。还验证保留期间改变文件大小的操作返回 -EPERM，而文件内的读写正常工作。</p><blockquote><p><strong>学习价值</strong>：系统梳理了文件保留的权限模型，有助于理解 VFS 层权限检查与 LUO 语义的结合。</p></blockquote><h3 id="cd7120856f0e-·-patch-v5-12-18-mm-shmem-luo-allow-preserving-tmpfs-files-1" tabindex="-1"><code>cd7120856f0e</code> · <a href="https://lore.kernel.org/all/20261123233924.3970932-13-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v5 12/18] mm/shmem_luo: Allow preserving tmpfs files</a> <a class="header-anchor" href="#cd7120856f0e-·-patch-v5-12-18-mm-shmem-luo-allow-preserving-tmpfs-files-1" aria-label="Permalink to &quot;`cd7120856f0e` · [[PATCH v5 12/18] mm/shmem_luo: Allow preserving tmpfs files](https://lore.kernel.org/all/20261123233924.3970932-13-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>通过移除 shmem_luo_can_preserve() 中的链接数检查，允许保留 tmpfs 挂载上的文件。该检查原本用于将保留限制在从无链接的 memfd 上，现在 tmpfs 文件可检索到用户创建的文件中，不再需要。用户空间可继续通过路径使用链接文件直到 Live Update；文件路径不被保留，用户需创建检索目标文件并可自行链接到期望路径。保留链接文件会影响所有通过路径打开它的用户，因为保留期间大小被冻结。</p><blockquote><p><strong>学习价值</strong>：展示了功能演进中放宽约束的设计权衡，以及保留语义对共享文件的多方影响。</p></blockquote><h3 id="_29815e309c55-·-patch-v5-11-18-mm-shmem-luo-retrieve-tmpfs-files-into-a-file-created-by-userspace" tabindex="-1"><code>29815e309c55</code> · <a href="https://lore.kernel.org/all/20261123233924.3970932-12-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v5 11/18] mm/shmem_luo: Retrieve tmpfs files into a file created by userspace</a> <a class="header-anchor" href="#_29815e309c55-·-patch-v5-11-18-mm-shmem-luo-retrieve-tmpfs-files-into-a-file-created-by-userspace" aria-label="Permalink to &quot;`29815e309c55` · [[PATCH v5 11/18] mm/shmem_luo: Retrieve tmpfs files into a file created by userspace](https://lore.kernel.org/all/20261123233924.3970932-12-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>新增将 tmpfs 挂载上保留的文件检索到用户空间创建文件中的支持：引入 struct liveupdate_shmem_retrieve_arg，用户空间通过 LIVEUPDATE_SESSION_RETRIEVE_FD 的 retrieve 参数传入目标文件描述符；同时在 struct shmem_luo_ser 中新增 SHMEM_LUO_FLAG_TMPFS 标志记录文件来自 tmpfs 挂载。原挂载在新内核中不存在，文件的路径、owner、mode、扩展属性等元数据均不保留。</p><blockquote><p><strong>学习价值</strong>：揭示了 LUO 跨内核升级传递 tmpfs 数据的序列化设计，对学习内核状态迁移机制很有价值。</p></blockquote><h3 id="_2be096e97a84-·-patch-v5-10-18-mm-shmem-luo-require-permission-to-preserve-a-file" tabindex="-1"><code>2be096e97a84</code> · <a href="https://lore.kernel.org/all/20261123233924.3970932-11-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v5 10/18] mm/shmem_luo: Require permission to preserve a file</a> <a class="header-anchor" href="#_2be096e97a84-·-patch-v5-10-18-mm-shmem-luo-require-permission-to-preserve-a-file" aria-label="Permalink to &quot;`2be096e97a84` · [[PATCH v5 10/18] mm/shmem_luo: Require permission to preserve a file](https://lore.kernel.org/all/20261123233924.3970932-11-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>该补丁为 shmem_luo（liveupdate 的 tmpfs 文件保留机制）增加权限约束：保留（preserve）一个文件要求以读方式打开且调用者具有写权限，例外是文件属主可以保留 immutable 文件或位于只读 superblock 的文件，但 append-only 文件被拒绝。文件被保留期间其大小对所有使用者冻结，truncate、fallocate() 和越界写入均返回 -EPERM，避免仅有只读 fd 的进程也能冻结文件大小。</p><blockquote><p><strong>学习价值</strong>：展示了内核中如何通过 fd 权限与文件属性（immutable、append-only）交叉校验来设计安全的系统调用语义，是理解 shmem/liveupdate 权限模型的好例子。</p></blockquote><h3 id="bfe3ef770c6f-·-patch-v5-09-18-mm-shmem-luo-don-t-make-early-retrieve-failures-permanent" tabindex="-1"><code>bfe3ef770c6f</code> · <a href="https://lore.kernel.org/all/20261123233924.3970932-10-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v5 09/18] mm/shmem_luo: Don&#39;t make early retrieve failures permanent</a> <a class="header-anchor" href="#bfe3ef770c6f-·-patch-v5-09-18-mm-shmem-luo-don-t-make-early-retrieve-failures-permanent" aria-label="Permalink to &quot;`bfe3ef770c6f` · [[PATCH v5 09/18] mm/shmem_luo: Don&#39;t make early retrieve failures permanent](https://lore.kernel.org/all/20261123233924.3970932-10-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>补丁将 shmem_luo_retrieve() 在开始恢复 folios 之前发生的失败标记为可重试：若没有任何 retrieve 成功，finish() 会像对待从未被 retrieve 的文件一样释放保留状态。在 folios 恢复之前保留状态未被消费，因此可留给后续可能成功的 retrieve（例如 memfd_alloc_file() 因 -ENOMEM 失败的场景）。但对于当前内核无法恢复的文件（如含有不支持的 seals），失败保持永久性。</p><blockquote><p><strong>学习价值</strong>：体现了内核错误处理中区分可重试与永久性失败的设计思路，对学习状态机式的错误恢复逻辑很有参考价值。</p></blockquote><h3 id="b7153ff3641e-·-patch-v5-08-18-liveupdate-let-file-handlers-retrieve-into-an-existing-file" tabindex="-1"><code>b7153ff3641e</code> · <a href="https://lore.kernel.org/all/20261123233924.3970932-9-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v5 08/18] liveupdate: Let file handlers retrieve into an existing file</a> <a class="header-anchor" href="#b7153ff3641e-·-patch-v5-08-18-liveupdate-let-file-handlers-retrieve-into-an-existing-file" aria-label="Permalink to &quot;`b7153ff3641e` · [[PATCH v5 08/18] liveupdate: Let file handlers retrieve into an existing file](https://lore.kernel.org/all/20261123233924.3970932-9-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>新增 liveupdate_claim_file() 和 liveupdate_unclaim_file()，供文件 handler 的 .retrieve() 回调在恢复保留状态前先让 LUO 接管目标文件。LUO 在 .retrieve() 返回后才正式管理新文件，但 shmem handler 需要恢复到已存在的 tmpfs 文件，必须在修改文件前确认 LUO 接受该文件，否则可能把状态恢复到一个被保留在 out-of-tree 位置的文件上。</p><blockquote><p><strong>学习价值</strong>：展示了回调式 API 中“先声明后操作”的时序设计，帮助理解 LUO 文件 handler 的生命周期与一致性约束。</p></blockquote><h3 id="_9b6b0b9f3334-·-patch-v5-07-18-liveupdate-add-helpers-to-track-the-files-that-luo-manages" tabindex="-1"><code>9b6b0b9f3334</code> · <a href="https://lore.kernel.org/all/20261123233924.3970932-8-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v5 07/18] liveupdate: Add helpers to track the files that LUO manages</a> <a class="header-anchor" href="#_9b6b0b9f3334-·-patch-v5-07-18-liveupdate-add-helpers-to-track-the-files-that-luo-manages" aria-label="Permalink to &quot;`9b6b0b9f3334` · [[PATCH v5 07/18] liveupdate: Add helpers to track the files that LUO manages](https://lore.kernel.org/all/20261123233924.3970932-8-dmatlack@google.com/)&quot;">​</a></h3><p><em>David Matlack (<a href="mailto:dmatlack@google.com" target="_blank" rel="noreferrer">dmatlack@google.com</a>)｜linux-mm</em></p><p>新增 luo_track_file() 和 luo_untrack_file() 辅助函数，用于向 luo_preserved_files xarray 添加/删除文件，取代原先对 xa_insert()/xa_erase() 与 luo_get_id() 的 open-coded 调用。这为后续让文件 handler 在 retrieve 时让 LUO 追踪目标文件做准备，将 key 生成和 -EBUSY 处理集中到一处。无功能性变化。</p><blockquote><p><strong>学习价值</strong>：一个典型的内核重构补丁，演示了如何通过提取 helper 函数消除重复代码并为后续扩展铺路，适合学习补丁演进的组织方式。</p></blockquote><h2 id="网络" tabindex="-1">网络 <a class="header-anchor" href="#网络" aria-label="Permalink to &quot;网络&quot;">​</a></h2><h3 id="_08e747fc240a-·-patch-net-v7-8-9-selftests-drv-net-psp-test-that-ipv4-psp-packets-aren-t-fragmented" tabindex="-1"><code>08e747fc240a</code> · <a href="https://lore.kernel.org/all/20261124010601.3995693-9-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net v7 8/9] selftests: drv-net: psp: test that ipv4 psp packets aren&#39;t fragmented</a> <a class="header-anchor" href="#_08e747fc240a-·-patch-net-v7-8-9-selftests-drv-net-psp-test-that-ipv4-psp-packets-aren-t-fragmented" aria-label="Permalink to &quot;`08e747fc240a` · [[PATCH net v7 8/9] selftests: drv-net: psp: test that ipv4 psp packets aren&#39;t fragmented](https://lore.kernel.org/all/20261124010601.3995693-9-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜lkml</em></p><p>该自测补丁验证 PSP（传输安全协议）加密的 IPv4 TCP 包在需要分片时会被丢弃（计入 IpFragFails）而不是以明文分片形式发出。测试通过设置两倍于设备 MTU 的路由 MTU 并配合 IP_PMTUDISC_OMIT 来触发分片场景，同时考虑了 TCP MTU probing 对 MSS 的影响。</p><blockquote><p><strong>学习价值</strong>：展示了 PSP 安全传输对分片明文泄露的防护测试方法，是学习网络自测框架和 MTU/MSS 交互细节的好素材。</p></blockquote><h3 id="_2c0fd536dc0c-·-patch-net-v7-9-9-net-mlx5e-psp-tso-replace-only-the-length-in-checksum-seed" tabindex="-1"><code>2c0fd536dc0c</code> · <a href="https://lore.kernel.org/all/20261124010601.3995693-10-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net v7 9/9] net/mlx5e: psp: tso: replace only the length in checksum seed</a> <a class="header-anchor" href="#_2c0fd536dc0c-·-patch-net-v7-9-9-net-mlx5e-psp-tso-replace-only-the-length-in-checksum-seed" aria-label="Permalink to &quot;`2c0fd536dc0c` · [[PATCH net v7 9/9] net/mlx5e: psp: tso: replace only the length in checksum seed](https://lore.kernel.org/all/20261124010601.3995693-10-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜lkml</em></p><p>修复 mlx5e 驱动中 PSP TCP 与 TSO 结合时的 checksum seed 计算问题：__tcp_transmit_skb() 先用 socket 地址和总长度计算校验和种子，mlx5e_psp_handle_tx_skb() 再重算，但应只替换长度部分而非地址。当 L3 头的目的地址是中间跳（如 IPv4 源路由选项 LSRR/SSRR 或 IPv6 路由头）时，重算地址会导致校验和错误。</p><blockquote><p><strong>学习价值</strong>：深入展示了 TSO 分段、传输层校验和 offload 与 PSP 加密的交互，是学习网卡驱动 offload 细节的高质量案例。</p></blockquote><h3 id="_0f48e6f5dea1-·-patch-net-v7-6-9-ipv6-don-t-send-redirects-for-decrypted-skbs-1" tabindex="-1"><code>0f48e6f5dea1</code> · <a href="https://lore.kernel.org/all/20261124010601.3995693-7-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net v7 6/9] ipv6: don&#39;t send redirects for decrypted skbs</a> <a class="header-anchor" href="#_0f48e6f5dea1-·-patch-net-v7-6-9-ipv6-don-t-send-redirects-for-decrypted-skbs-1" aria-label="Permalink to &quot;`0f48e6f5dea1` · [[PATCH net v7 6/9] ipv6: don&#39;t send redirects for decrypted skbs](https://lore.kernel.org/all/20261124010601.3995693-7-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜lkml</em></p><p>修复 IPv6 转发路径上的明文泄露：当 ip6_forward() 将包从进入的接口转发回去时，会通过 ndisc_send_redirect() 发送 NDISC Redirect，其 Redirected Header 选项会引用原包内容。若设备已解密该包（skb-&gt;decrypted 置位），redirect 会把明文片段发回网络，因此对已解密的 skb 不再发送 redirect。IPv4 的 redirect 走 __icmp_send() 已被前序补丁覆盖。</p><blockquote><p><strong>学习价值</strong>：展示了加密流量与 ICMPv6 redirect 的交互泄露问题，对理解 skb-&gt;decrypted 标志和 ndisc 实现很有帮助。</p></blockquote><h3 id="_7e9fef4a9e47-·-patch-net-v7-7-9-selftests-drv-net-psp-test-ipv6-tcp-socket-with-extension-headers" tabindex="-1"><code>7e9fef4a9e47</code> · <a href="https://lore.kernel.org/all/20261124010601.3995693-8-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net v7 7/9] selftests: drv-net: psp: test ipv6 tcp socket with extension headers</a> <a class="header-anchor" href="#_7e9fef4a9e47-·-patch-net-v7-7-9-selftests-drv-net-psp-test-ipv6-tcp-socket-with-extension-headers" aria-label="Permalink to &quot;`7e9fef4a9e47` · [[PATCH net v7 7/9] selftests: drv-net: psp: test ipv6 tcp socket with extension headers](https://lore.kernel.org/all/20261124010601.3995693-8-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜lkml</em></p><p>该自测补丁分三个阶段测试带 IPv6 扩展头的 PSP TCP socket：无选项时数据正常收发；设置扩展头（目的选项、逐跳选项或路由头）后包被丢弃且数据保持排队；移除选项后排队数据和新数据恢复发送。验证设备对带扩展头的 PSP 包的丢弃行为。</p><blockquote><p><strong>学习价值</strong>：演示了如何编写分阶段验证内核网络行为变化的自测，有助于学习 IPv6 扩展头处理和 PSP 测试设计。</p></blockquote><h3 id="eb8c7d3a4144-·-patch-net-net-bridge-switchdev-clear-the-hwdom-of-a-port-that-stops-the-offload" tabindex="-1"><code>eb8c7d3a4144</code> · <a href="https://lore.kernel.org/all/20261124011639.990261-1-koralilgun@gmail.com/" target="_blank" rel="noreferrer">[PATCH net] net: bridge: switchdev: clear the hwdom of a port that stops the offload</a> <a class="header-anchor" href="#eb8c7d3a4144-·-patch-net-net-bridge-switchdev-clear-the-hwdom-of-a-port-that-stops-the-offload" aria-label="Permalink to &quot;`eb8c7d3a4144` · [[PATCH net] net: bridge: switchdev: clear the hwdom of a port that stops the offload](https://lore.kernel.org/all/20261124011639.990261-1-koralilgun@gmail.com/)&quot;">​</a></h3><p><em>Koral Ilgun (<a href="mailto:koralilgun@gmail.com" target="_blank" rel="noreferrer">koralilgun@gmail.com</a>)｜netdev</em></p><p>修复 bridge switchdev 的 hwdom 泄漏问题：当 switchdev 驱动停止 offload 但端口仍留在 bridge 中时（如 DSA 中最后一个交换端口离开仍作为 bridge port 的 LAG），nbp_switchdev_del() 不会释放该端口的 hwdom，导致 hwdom 永久占用。泄漏 BR_HWDOM_MAX - 1 次后，nbp_switchdev_hwdom_get() 会失败。补丁在端口停止 offload 时清除其 hwdom。</p><blockquote><p><strong>学习价值</strong>：展示了资源引用计数泄漏的典型成因（资源持有者与释放者不匹配），对学习 bridge/switchdev/DSA 的 hwdom 机制和调试此类泄漏很有帮助。</p></blockquote><h2 id="rust-in-linux" tabindex="-1">Rust in Linux <a class="header-anchor" href="#rust-in-linux" aria-label="Permalink to &quot;Rust in Linux&quot;">​</a></h2><h3 id="_7e4b2fb588fe-·-patch-v2-samples-rust-dma-add-missing-newline-in-dev-info-call" tabindex="-1"><code>7e4b2fb588fe</code> · <a href="https://lore.kernel.org/all/20261123230618.375172-1-saref012@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2] samples: rust_dma: add missing newline in dev_info! call</a> <a class="header-anchor" href="#_7e4b2fb588fe-·-patch-v2-samples-rust-dma-add-missing-newline-in-dev-info-call" aria-label="Permalink to &quot;`7e4b2fb588fe` · [[PATCH v2] samples: rust_dma: add missing newline in dev_info! call](https://lore.kernel.org/all/20261123230618.375172-1-saref012@gmail.com/)&quot;">​</a></h3><p><em>Ivan Borovyk (<a href="mailto:saref012@gmail.com" target="_blank" rel="noreferrer">saref012@gmail.com</a>)｜rust-for-linux</em></p><p>修复 rust_dma 示例代码中 PinnedDrop::drop() 里 dev_info! 调用格式串缺少结尾换行符 &#39;\\n&#39; 的问题，使其与文件中其他 dev_<em>!() 和 pr_</em>!() 宏的约定保持一致。v2 修正了 commit message 中错误的位置描述（在 drop() 而非 probe()）。</p><blockquote><p><strong>学习价值</strong>：虽是琐碎修复，但提示了 Rust 内核代码中日志宏的格式约定，适合了解 rust-for-linux 社区的补丁规范流程。</p></blockquote><h3 id="_57739823b928-·-patch-rust-workqueue-fix-safety-comments-in-pin-run" tabindex="-1"><code>57739823b928</code> · <a href="https://lore.kernel.org/all/20261123-rust-workqueue-safety-comment-v1-1-48e4f9b35c30@gmail.com/" target="_blank" rel="noreferrer">[PATCH] rust: workqueue: fix SAFETY comments in Pin&gt; run()</a> <a class="header-anchor" href="#_57739823b928-·-patch-rust-workqueue-fix-safety-comments-in-pin-run" aria-label="Permalink to &quot;`57739823b928` · [[PATCH] rust: workqueue: fix SAFETY comments in Pin&gt; run()](https://lore.kernel.org/all/20261123-rust-workqueue-safety-comment-v1-1-48e4f9b35c30@gmail.com/)&quot;">​</a></h3><p><em>Andrea Tontini (<a href="mailto:andreatontinidev@gmail.com" target="_blank" rel="noreferrer">andreatontinidev@gmail.com</a>)｜rust-for-linux</em></p><p>修复 rust workqueue 中 Pin&lt;KBox&lt;T&gt;&gt; 的 WorkItemPointer 实现里 run() 函数的 SAFETY 注释：该实现从 Arc&lt;T&gt; 版本复制而来，注释仍声称指针来自 Arc::into_raw，但对应的 RawWorkItem::__enqueue 实际通过 KBox::into_raw 获取指针（这也是后续 KBox::from_raw 保持 sound 的原因）。补丁仅更新注释，无功能变化。</p><blockquote><p><strong>学习价值</strong>：SAFETY 注释是 Rust 内核代码正确性的核心文档，此例说明复制代码时注释失同步会误导 unsafe 正确性审查，对学习 unsafe Rust 规范很有意义。</p></blockquote><h3 id="a03cead12858-·-rfc-patch-3-3-rust-dma-require-device-configuration-before-dma" tabindex="-1"><code>a03cead12858</code> · <a href="https://lore.kernel.org/all/20261123203926.1787169-4-kernel@matt3o12.de/" target="_blank" rel="noreferrer">[RFC PATCH 3/3] rust: dma: require device configuration before DMA</a> <a class="header-anchor" href="#a03cead12858-·-rfc-patch-3-3-rust-dma-require-device-configuration-before-dma" aria-label="Permalink to &quot;`a03cead12858` · [[RFC PATCH 3/3] rust: dma: require device configuration before DMA](https://lore.kernel.org/all/20261123203926.1787169-4-kernel@matt3o12.de/)&quot;">​</a></h3><p><em>Matteo Kloiber (<a href="mailto:kernel@matt3o12.de" target="_blank" rel="noreferrer">kernel@matt3o12.de</a>)｜rust-for-linux</em></p><p>针对 Rust 驱动可在未设置 DMA 参数（streaming mask、coherent mask、最大 segment size 等）时就分配或映射 DMA 内存的问题，引入 DMA Setup token，加入 PCI 和 platform 总线传给 probe() 的 InitTokens 中。未设置时将沿用总线默认值或前一个驱动遗留的值（Nova 驱动曾因此出过 bug）。不使用 DMA 的驱动可以丢弃该 token。</p><blockquote><p><strong>学习价值</strong>：展示了用 Rust 类型系统（token/handle 模式）在编译期强制 API 调用顺序的思路，是 Rust in Linux 安全设计的优秀范例。</p></blockquote><h3 id="df3aa699c053-·-rfc-patch-2-3-gpu-nova-core-build-gpu-inside-pin-init-scope" tabindex="-1"><code>df3aa699c053</code> · <a href="https://lore.kernel.org/all/20261123203926.1787169-3-kernel@matt3o12.de/" target="_blank" rel="noreferrer">[RFC PATCH 2/3] gpu: nova-core: build Gpu inside pin_init_scope</a> <a class="header-anchor" href="#df3aa699c053-·-rfc-patch-2-3-gpu-nova-core-build-gpu-inside-pin-init-scope" aria-label="Permalink to &quot;`df3aa699c053` · [[RFC PATCH 2/3] gpu: nova-core: build Gpu inside pin_init_scope](https://lore.kernel.org/all/20261123203926.1787169-3-kernel@matt3o12.de/)&quot;">​</a></h3><p><em>Matteo Kloiber (<a href="mailto:kernel@matt3o12.de" target="_blank" rel="noreferrer">kernel@matt3o12.de</a>)｜rust-for-linux</em></p><p>为 nova-core GPU 驱动重构 Gpu::new()：将 try_pin_init!() 初始化器包进 pin_init_scope()，在进入前计算 chip spec，并在 spec 确定后立即设置 DMA mask 和最大 segment size（早于 Tree::new()）。这是为后续把 DMA setter 替换为返回 handle 的配置步骤做准备，将重排缩进从后续补丁中剥离。除 DMA 参数设置时机提前外无功能变化。</p><blockquote><p><strong>学习价值</strong>：演示了如何用 pin_init_scope() 组织 Rust 内核驱动的分阶段初始化，以及拆分重构补丁以降低 review 负担的实践。</p></blockquote><h3 id="e8c018cccb5d-·-rfc-patch-1-3-rust-pci-platform-pass-inittokens-to-probe" tabindex="-1"><code>e8c018cccb5d</code> · <a href="https://lore.kernel.org/all/20261123203926.1787169-2-kernel@matt3o12.de/" target="_blank" rel="noreferrer">[RFC PATCH 1/3] rust: pci, platform: pass InitTokens to probe()</a> <a class="header-anchor" href="#e8c018cccb5d-·-rfc-patch-1-3-rust-pci-platform-pass-inittokens-to-probe" aria-label="Permalink to &quot;`e8c018cccb5d` · [[RFC PATCH 1/3] rust: pci, platform: pass InitTokens to probe()](https://lore.kernel.org/all/20261123203926.1787169-2-kernel@matt3o12.de/)&quot;">​</a></h3><p><em>Matteo Kloiber (<a href="mailto:kernel@matt3o12.de" target="_blank" rel="noreferrer">kernel@matt3o12.de</a>)｜rust-for-linux</em></p><p>为 PCI 和 platform 总线引入 InitTokens 结构体并传给 Driver::probe()，用于承载仅在设备绑定期间可用的能力 token（如 DMA 配置）。该结构标记为 #[non_exhaustive]，驱动用 <code>..</code> 解构，因此后续新增 token 不会破坏现有驱动，避免了每次都为 probe() 加参数而波及所有驱动。当前结构尚不携带任何 token。</p><blockquote><p><strong>学习价值</strong>：展示了 Rust 内核 API 演进中 #[non_exhaustive] 与解构模式如何实现向后兼容的接口扩展，对设计可演进的驱动框架很有启发。</p></blockquote><h3 id="_7008bcfb6f4d-·-rfc-patch-0-3-rust-dma-require-device-configuration-before-dma-1" tabindex="-1"><code>7008bcfb6f4d</code> · <a href="https://lore.kernel.org/all/20261123203926.1787169-1-kernel@matt3o12.de/" target="_blank" rel="noreferrer">[RFC PATCH 0/3] rust: dma: require device configuration before DMA</a> <a class="header-anchor" href="#_7008bcfb6f4d-·-rfc-patch-0-3-rust-dma-require-device-configuration-before-dma-1" aria-label="Permalink to &quot;`7008bcfb6f4d` · [[RFC PATCH 0/3] rust: dma: require device configuration before DMA](https://lore.kernel.org/all/20261123203926.1787169-1-kernel@matt3o12.de/)&quot;">​</a></h3><p><em>Matteo Kloiber (<a href="mailto:kernel@matt3o12.de" target="_blank" rel="noreferrer">kernel@matt3o12.de</a>)｜rust-for-linux</em></p><p>该 RFC 源自关于 max_seg_size 的讨论，实现了通过 InitTokens 传递给 probe() 的 DMA setup token 机制。驱动必须先调用 configure() 消耗 token 并设置 dma::Params（如 streaming_mask、coherent_mask、max_seg_size），才能获得可复制的 dma::Handle 并进行 Coherent 分配或映射。这从类型系统层面强制驱动在 DMA 操作前正确完成设备配置。</p><blockquote><p><strong>学习价值</strong>：展示了如何用 Rust 类型状态（typestate）模式将内核 DMA 配置顺序编码进 API，是学习 Rust 安全抽象设计的优秀案例。</p></blockquote><h3 id="cb2c2b148d43-·-patch-rust-omit-visibility-pragma-when-calling-bindgen" tabindex="-1"><code>cb2c2b148d43</code> · <a href="https://lore.kernel.org/all/20261123171042.62348-2-ardb@kernel.org/" target="_blank" rel="noreferrer">[PATCH] rust: Omit visibility pragma when calling bindgen</a> <a class="header-anchor" href="#cb2c2b148d43-·-patch-rust-omit-visibility-pragma-when-calling-bindgen" aria-label="Permalink to &quot;`cb2c2b148d43` · [[PATCH] rust: Omit visibility pragma when calling bindgen](https://lore.kernel.org/all/20261123171042.62348-2-ardb@kernel.org/)&quot;">​</a></h3><p><em>Ard Biesheuvel (<a href="mailto:ardb@kernel.org" target="_blank" rel="noreferrer">ardb@kernel.org</a>)｜rust-for-linux</em></p><p>bindgen 用于从 Linux 内核头文件生成 Rust FFI 定义，但它默认沿用用户空间习惯，忽略 hidden visibility 的 ELF 符号。内核中 hidden visibility 配合 PIC 代码生成用于省略 GOT 槽位，并支持对全局对象使用 &quot;i&quot; 内联汇编约束。该补丁在定义 <strong>BINDGEN</strong> 时屏蔽相关 pragma，使 bindgen 正确处理内核符号。</p><blockquote><p><strong>学习价值</strong>：揭示了内核与用户空间在符号可见性语义上的差异，有助于理解 Rust FFI 生成工具与内核构建细节的交互。</p></blockquote><h3 id="_4e74c1cf5457-·-patch-v3-rust-bindgen-preserve-sched-statistics-alignment" tabindex="-1"><code>4e74c1cf5457</code> · <a href="https://lore.kernel.org/all/20261123-fix-schedstats-bindgen-layout-v3-1-ef7e83c32b42@gmail.com/" target="_blank" rel="noreferrer">[PATCH v3] rust: bindgen: Preserve sched_statistics alignment</a> <a class="header-anchor" href="#_4e74c1cf5457-·-patch-v3-rust-bindgen-preserve-sched-statistics-alignment" aria-label="Permalink to &quot;`4e74c1cf5457` · [[PATCH v3] rust: bindgen: Preserve sched_statistics alignment](https://lore.kernel.org/all/20261123-fix-schedstats-bindgen-layout-v3-1-ef7e83c32b42@gmail.com/)&quot;">​</a></h3><p><em>Peder Bergan via B4 Relay (<a href="mailto:devnull+peder.bergan.gmail.com@kernel.org" target="_blank" rel="noreferrer">devnull+peder.bergan.gmail.com@kernel.org</a>)｜rust-for-linux</em></p><p>当 CONFIG_SCHEDSTATS 关闭时，struct sched_statistics 为空但仍保持 cache-line 对齐，而 bindgen 会忽略空类型的对齐属性；bindgen 0.73.2 又不再为 over-aligned 字段强制填充 padding，导致生成的 task_struct 中字段错位。在 arm64 构建上，Rust Binder 通过 CurrentTask::mm() 读到错误指针，使 mmap() 返回 -EINVAL。修复方式是将 sched_statistics 标记为 opaque，让 bindgen 直接采用 C 侧的大小和对齐信息。</p><blockquote><p><strong>学习价值</strong>：一个典型的 FFI 布局不匹配 bug 案例，说明跨语言结构体布局一致性对内核正确性的关键影响。</p></blockquote><h2 id="跟踪与性能" tabindex="-1">跟踪与性能 <a class="header-anchor" href="#跟踪与性能" aria-label="Permalink to &quot;跟踪与性能&quot;">​</a></h2><h3 id="_94daa9e8f56f-·-zstd-1-6-released-with-many-fixes-new-performance-optimizations" tabindex="-1"><code>94daa9e8f56f</code> · <a href="https://www.phoronix.com/news/Zstandard-Zstd-1.6" target="_blank" rel="noreferrer">Zstd 1.6 Released With Many Fixes, New Performance Optimizations</a> <a class="header-anchor" href="#_94daa9e8f56f-·-zstd-1-6-released-with-many-fixes-new-performance-optimizations" aria-label="Permalink to &quot;`94daa9e8f56f` · [Zstd 1.6 Released With Many Fixes, New Performance Optimizations](https://www.phoronix.com/news/Zstandard-Zstd-1.6)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Zstandard 1.6.0 发布，这是继 v1.5.7 之后时隔一年半的重大版本更新，包含大量修复和新的性能优化。Zstd 是 Linux 内核中广泛使用的压缩算法，用于内核压缩、Btrfs/SquashFS 文件系统压缩、F2FS 以及 zram 等场景。</p><blockquote><p><strong>学习价值</strong>：了解 Zstd 新版本动态有助于理解内核各子系统（fs、mm/zram）对用户态压缩库的依赖与演进。</p></blockquote><h3 id="ab674d6c1d5c-·-amd-epyc-zen-6-vs-zen-1-performance-12-1x-geo-mean-in-less-than-10-years-up-to-133x-in-ai" tabindex="-1"><code>ab674d6c1d5c</code> · <a href="https://www.phoronix.com/review/amd-epyc-9006-7601" target="_blank" rel="noreferrer">AMD EPYC Zen 6 vs. Zen 1 Performance: 12.1x Geo Mean In Less Than 10 Years, Up To 133x In AI</a> <a class="header-anchor" href="#ab674d6c1d5c-·-amd-epyc-zen-6-vs-zen-1-performance-12-1x-geo-mean-in-less-than-10-years-up-to-133x-in-ai" aria-label="Permalink to &quot;`ab674d6c1d5c` · [AMD EPYC Zen 6 vs. Zen 1 Performance: 12.1x Geo Mean In Less Than 10 Years, Up To 133x In AI](https://www.phoronix.com/review/amd-epyc-9006-7601)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Phoronix 对比了新一代 EPYC 9006 &quot;Venice&quot; Zen 6 服务器处理器与十年前第一代 EPYC &quot;Naples&quot; Zen 1 的性能，几何平均提升达 12.1 倍，AI 负载最高提升 133 倍。这是硬件性能评测，不涉及内核代码。</p><blockquote><p><strong>学习价值</strong>：对内核学习价值有限，可作为了解服务器硬件十年演进对内核优化（如 per-CPU、NUMA）背景的参考。</p></blockquote><h2 id="版本发布动态" tabindex="-1">版本发布动态 <a class="header-anchor" href="#版本发布动态" aria-label="Permalink to &quot;版本发布动态&quot;">​</a></h2><h3 id="_67e09ae00495-·-next-20261123-linux-next" tabindex="-1"><code>67e09ae00495</code> · <a href="https://www.kernel.org/#kernel.org-linux-next-next-20261123-2026-11-23" target="_blank" rel="noreferrer">next-20261123: linux-next</a> <a class="header-anchor" href="#_67e09ae00495-·-next-20261123-linux-next" aria-label="Permalink to &quot;`67e09ae00495` · [next-20261123: linux-next](https://www.kernel.org/#kernel.org-linux-next-next-20261123-2026-11-23)&quot;">​</a></h3><p><em>kernel.org</em></p><p>linux-next 于 2026 年 11 月 23 日发布 next-20261123 版本，作为合并到主线前的集成测试树。</p><blockquote><p><strong>学习价值</strong>：跟踪 linux-next 版本有助于学习者提前了解即将进入主线的代码变更。</p></blockquote><h2 id="其他动态" tabindex="-1">其他动态 <a class="header-anchor" href="#其他动态" aria-label="Permalink to &quot;其他动态&quot;">​</a></h2><h3 id="f9d5991953f5-·-ladybird-web-browser-engine-reaches-alpha" tabindex="-1"><code>f9d5991953f5</code> · <a href="https://www.phoronix.com/news/Ladybird-Browser-Alpha" target="_blank" rel="noreferrer">Ladybird Web Browser/Engine Reaches Alpha</a> <a class="header-anchor" href="#f9d5991953f5-·-ladybird-web-browser-engine-reaches-alpha" aria-label="Permalink to &quot;`f9d5991953f5` · [Ladybird Web Browser/Engine Reaches Alpha](https://www.phoronix.com/news/Ladybird-Browser-Alpha)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Ladybird 浏览器进入 alpha 阶段，它是一个从零开始构建、拥有独立 web 引擎的开源桌面浏览器。该项目与 Linux 内核开发无直接关系。</p><blockquote><p><strong>学习价值</strong>：与内核学习基本无关，仅可作为开源生态背景了解。</p></blockquote><h3 id="f86726747a9b-·-mesa-27-0-radeonsi-gallium3d-disables-radeon-kernel-driver-support-by-default" tabindex="-1"><code>f86726747a9b</code> · <a href="https://www.phoronix.com/news/RadeonSI-Radeon-Disable-Default" target="_blank" rel="noreferrer">Mesa 27.0 RadeonSI Gallium3D Disables Radeon Kernel Driver Support By Default</a> <a class="header-anchor" href="#f86726747a9b-·-mesa-27-0-radeonsi-gallium3d-disables-radeon-kernel-driver-support-by-default" aria-label="Permalink to &quot;`f86726747a9b` · [Mesa 27.0 RadeonSI Gallium3D Disables Radeon Kernel Driver Support By Default](https://www.phoronix.com/news/RadeonSI-Radeon-Disable-Default)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Mesa 27.0 的 RadeonSI Gallium3D 驱动默认禁用对旧版 Radeon 内核驱动的兼容支持，以推动用户迁移到 AMDGPU 内核驱动。受影响的是 GCN 1.0/1.1 等早期 GPU，它们约一年前已在 AMDGPU 驱动上达到功能对等，目前仍可通过选项重新启用。</p><blockquote><p><strong>学习价值</strong>：展示了用户态图形栈（Mesa）与内核 DRM 驱动（radeon vs amdgpu）的演进关系，对理解 GPU 驱动迁移有参考价值。</p></blockquote><h2 id="深读候选" tabindex="-1">深读候选 <a class="header-anchor" href="#深读候选" aria-label="Permalink to &quot;深读候选&quot;">​</a></h2><p>以下条目适合优先深读（按条目前的 id 手动生成）：</p><ul><li><code>f1a6305a1f0f</code> · <a href="https://lore.kernel.org/all/6b04e3d0.44b41460.34b83f.0035.GAE@google.com/" target="_blank" rel="noreferrer">[syzbot] [kernfs?] KASAN: slab-use-after-free Read in kernfs_find_ns</a></li><li><code>0f48e6f5dea1</code> · <a href="https://lore.kernel.org/all/20261124010601.3995693-7-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net v7 6/9] ipv6: don&#39;t send redirects for decrypted skbs</a></li><li><code>032ef42c1a39</code> · <a href="https://lore.kernel.org/all/20261124003145.80705-1-harpatil@redhat.com/" target="_blank" rel="noreferrer">[RFC PATCH] mm: memcontrol: let a cgroup opt out of HugeTLB accounting</a></li><li><code>cd7120856f0e</code> · <a href="https://lore.kernel.org/all/20261123233924.3970932-13-dmatlack@google.com/" target="_blank" rel="noreferrer">[PATCH v5 12/18] mm/shmem_luo: Allow preserving tmpfs files</a></li><li><code>7008bcfb6f4d</code> · <a href="https://lore.kernel.org/all/20261123203926.1787169-1-kernel@matt3o12.de/" target="_blank" rel="noreferrer">[RFC PATCH 0/3] rust: dma: require device configuration before DMA</a></li></ul>',171)])])}const h=a(l,[["render",n]]);export{p as __pageData,h as default};
